void main() {
  // Step 1: If-Else - Grade Checker
  int marks = 85;

  if (marks >= 90) {
    print("Grade: A");
  } else if (marks >= 75) {
    print("Grade: B");
  } else {
    print("Grade: C");
  }

  // Step 2: For Loop - Display subjects
  List<String> subjects = ["Math", "Science", "English"];
  for (int i = 0; i < subjects.length; i++) {
    print("Subject ${i + 1}: ${subjects[i]}");
  }

  // Step 3: While Loop - Countdown
  int countdown = 5;
  while (countdown > 0) {
    print("Timer: $countdown");
    countdown--;
  }
}
